/**
 * Generative mode: image/prompt -> TRELLIS.2 base mesh -> verified game-ready GLB.
 *
 * The counterpart to buildFromSpec (run.ts). Where that builds geometry from a
 * SceneSpec deterministically, this takes a mesh generated by TRELLIS.2 and runs
 * it through the King3D quality pipeline: import -> best-effort repair ->
 * assign material (where missing) -> UV unwrap (where missing) -> decimate to
 * budget -> export -> re-import verify -> gates.
 *
 * TRELLIS runs in geometry-only mode (its textured-GLB export depends on the
 * non-commercial nvdiffrast rasterizer), so the base mesh arrives with no
 * material and no UV; King3D supplies both here. That makes the output a clean,
 * King3D-owned PBR asset and keeps the whole path free of nvdiffrast.
 *
 * The generative step itself (the model) is the one non-deterministic part and
 * lives behind the HTTP client; everything after the base mesh is on disk is as
 * deterministic and reproducible as the procedural pipeline, driven entirely by
 * the GenerativeSpec written alongside the run.
 */
import { mkdir, writeFile } from "node:fs/promises";
import { isAbsolute, join } from "node:path";
import { loadConfig, paths, type Ai3dConfig } from "../core/config.ts";
import { Ai3dError } from "../core/errors.ts";
import { createLogger } from "../core/logger.ts";
import { acquireBackend } from "../integrations/blender/index.ts";
import { Batch } from "../integrations/blender/backend.ts";
import type { BatchOutcome, BlenderBackend, JobContext } from "../integrations/blender/backend.ts";
import { acquireTrellis, type TrellisProvider } from "../integrations/trellis/client.ts";
import type { GenerativeSpec } from "../spec/generative-spec.ts";
import { buildExportVerifyBatch } from "./builder.ts";
import { evaluateGeneratedGates } from "./generative-gates.ts";
import type { GateReport } from "./gates.ts";
import { newRunId, runPaths, type RunPaths, type StageTiming } from "./run.ts";

const log = createLogger("generative");

export interface GenerativeBuildOptions {
  runId?: string;
  config?: Ai3dConfig;
  /** Override the provider (tests inject a mock directly). */
  provider?: TrellisProvider;
  skipExport?: boolean;
  onStage?: (name: string, detail: string) => void;
}

export interface GenerativeBuildResult {
  runId: string;
  paths: RunPaths;
  baseMeshPath: string;
  report: GateReport;
  timings: StageTiming[];
  exported: boolean;
}

export async function buildFromGenerated(
  spec: GenerativeSpec,
  options: GenerativeBuildOptions = {},
): Promise<GenerativeBuildResult> {
  const runId = options.runId ?? newRunId("gen");
  const rp = runPaths(runId);
  const config = options.config ?? loadConfig();
  const timings: StageTiming[] = [];
  const stage = options.onStage ?? (() => undefined);

  const specPath = join(rp.dir, "generative-spec.json");
  const baseMeshPath = join(rp.dir, "source", "base.glb");

  await mkdir(rp.dir, { recursive: true });
  await mkdir(join(rp.dir, "source"), { recursive: true });
  await writeFile(specPath, JSON.stringify(spec, null, 2), "utf8");

  // --- generate (the one non-deterministic stage) -------------------------
  const provider = options.provider ?? acquireTrellis(config);
  stage("generate", `requesting base mesh from TRELLIS (${provider.kind})`);
  // The reference image is copied into the run directory, so a relative
  // source.image resolves against it - keeping the run self-contained.
  const imagePath = spec.source.image
    ? isAbsolute(spec.source.image)
      ? spec.source.image
      : join(rp.dir, spec.source.image)
    : undefined;
  const genStart = Date.now();
  const generated = await provider.generate(
    {
      ...(imagePath ? { imagePath } : {}),
      ...(spec.source.prompt ? { prompt: spec.source.prompt } : {}),
      ...(spec.generator.seed !== undefined ? { seed: spec.generator.seed } : {}),
    },
    baseMeshPath,
  );
  timings.push({ stage: "generate", ms: Date.now() - genStart, blenderMs: -1 });

  const { backend, coldStart } = await acquireBackend(config, { onProgress: (m) => stage("daemon", m) });
  if (coldStart) stage("daemon", "started a new Blender daemon");

  try {
    // --- import + repair --------------------------------------------------
    stage("repair", "importing base mesh and running best-effort cleanup");
    const importBatch = new Batch()
      .add("import.glb", { path: baseMeshPath, reset_scene: true })
      .add("repair.clean", {
        objects: [],
        weld_distance_m: spec.repair.weld_distance_m,
        delete_loose: spec.repair.delete_loose,
        dissolve_degenerate: spec.repair.dissolve_degenerate,
        fill_holes: spec.repair.fill_holes,
        recalc_normals: spec.repair.recalc_normals,
      });
    await run(backend, importBatch, { saveBlend: rp.blend }, timings, "repair");

    // --- pre-optimise inspection -----------------------------------------
    // Get the mesh names, which already carry a UV map, and which already carry a
    // material. TRELLIS runs in geometry-only mode, so in practice the base mesh
    // has neither: King3D supplies both below. (A mesh that *does* arrive with a
    // UV is left alone, so this also works if a textured GLB is ever fed in.)
    stage("inspect", "measuring repaired mesh");
    const preInspect = new Batch().add("inspect.all", { objects: [] });
    const preOutcome = await run(backend, preInspect, { loadBlend: rp.blend }, timings, "inspect_pre");
    const preMeshes = preInspect.resultAt(preOutcome, 0, "inspect.all").meshes;
    const needUv = preMeshes.filter((m) => !m.has_uv).map((m) => m.name);
    const needMaterial = preMeshes.filter((m) => m.material_slots === 0).map((m) => m.name);

    // --- materialise ------------------------------------------------------
    // Geometry-only base meshes have no material; assign the spec's default so
    // the exported GLB has a real PBR slot and the materials_assigned gate passes.
    // Runs regardless of skipExport so the gates always score a materialised mesh.
    if (needMaterial.length > 0) {
      stage("material", `assigning default material to ${needMaterial.length} mesh(es)`);
      const matBatch = new Batch();
      for (const name of needMaterial) {
        matBatch.add("material.assign", {
          object: name,
          material: {
            name: spec.material.name,
            base_color: spec.material.base_color,
            metallic: spec.material.metallic,
            roughness: spec.material.roughness,
          },
          slot: 0,
        });
      }
      await run(backend, matBatch, { loadBlend: rp.blend, saveBlend: rp.blend }, timings, "material");
    }

    let exported: { tris: number; objects: number; sizeBytes: number } | undefined;

    if (!options.skipExport) {
      stage("export", `unwrap ${needUv.length} mesh(es), decimate to ${spec.quality.target_tris} tris, write GLB`);
      await mkdir(join(rp.dir, "export"), { recursive: true });
      const exportBatch = new Batch();
      if (spec.quality.require_uv && needUv.length > 0) {
        exportBatch.add("uv.unwrap", { objects: needUv, method: "SMART", angle_limit: 66, island_margin: 0.02 });
      }
      // min_ratio caps how aggressive a single collapse pass gets. (Geometry-only
      // meshes carry no baked texture, so decimation has no PBR bake to distort;
      // King3D's own UV is assigned fresh after this.)
      exportBatch.add("optimize.decimate", { objects: [], target_tris: spec.quality.target_tris, min_ratio: 0.1 });
      exportBatch.add("export.glb", { output: rp.glb, objects: [], apply_modifiers: true, y_up: true });
      const exportOutcome = await run(backend, exportBatch, { loadBlend: rp.blend, saveBlend: rp.blend }, timings, "export");
      const glb = exportBatch.resultAt(exportOutcome, exportBatch.size - 1, "export.glb");

      stage("verify", "re-importing the GLB to prove it loads");
      const verifyBatch = buildExportVerifyBatch(rp.glb);
      const verifyOutcome = await run(backend, verifyBatch, { loadBlend: rp.blend }, timings, "verify");
      const imported = verifyBatch.resultAt(verifyOutcome, 0, "import.glb");
      exported = { tris: imported.total_tris, objects: imported.objects.length, sizeBytes: glb.size_bytes };
    }

    // Measure after export so the gates score the mesh that was actually shipped.
    const finalInspect = new Batch().add("inspect.all", { objects: [] }).add("scene.info", {});
    const finalOutcome = await run(backend, finalInspect, { loadBlend: rp.blend }, timings, "inspect_final");
    const finalMeshes = finalInspect.resultAt(finalOutcome, 0, "inspect.all").meshes;
    const scene = finalInspect.resultAt(finalOutcome, 1, "scene.info");

    const report = evaluateGeneratedGates({
      spec,
      meshes: finalMeshes,
      scene,
      ...(exported ? { exported } : {}),
    });

    await writeFile(
      rp.report,
      JSON.stringify(
        {
          run_id: runId,
          spec_id: spec.id,
          mode: "generative",
          generator: spec.generator,
          source_mesh: generated.meta,
          created_at: new Date().toISOString(),
          passed: report.passed,
          scores: report.scores,
          gates: report.gates,
          timings,
          artifacts: {
            spec: specPath,
            base_mesh: baseMeshPath,
            blend: rp.blend,
            ...(exported ? { glb: rp.glb } : {}),
          },
        },
        null,
        2,
      ),
      "utf8",
    );

    log.info("generative run complete", { runId, passed: report.passed });
    return { runId, paths: rp, baseMeshPath, report, timings, exported: exported !== undefined };
  } finally {
    await backend.close();
  }
}

/** Run one batch, record its timing, and fail loudly with the offending command. */
async function run(
  backend: BlenderBackend,
  batch: Batch,
  context: JobContext,
  timings: StageTiming[],
  name: string,
): Promise<BatchOutcome> {
  const started = Date.now();
  const outcome = await batch.run(backend, { ...context, cwd: paths.root });
  timings.push({ stage: name, ms: Date.now() - started, blenderMs: outcome.timings?.batch_ms ?? -1 });

  if (!outcome.ok) {
    const index = outcome.responses.findIndex((r) => !r.ok);
    const failed = outcome.responses[index];
    throw new Ai3dError(
      "BLENDER_COMMAND_FAILED",
      `stage "${name}" failed at ${batch.requests[index]?.cmd}: ${failed?.error?.message}`,
      { stage: name, command: batch.requests[index]?.cmd, error: failed?.error, logs: failed?.logs },
    );
  }
  return outcome;
}
